import json
data = json.load(open('outline.json'))
print('VALID')
for act_name in ['act_one', 'act_two', 'act_three']:
    act = data[act_name]
    chapters = act['key_chapters']
    print(f'{act_name}: {len(chapters)} chapters')
    for ch in chapters:
        scenes = ch['scene_sequence']
        print(f'  Chapter {ch[\"chapter_number\"]}: {len(scenes)} scenes')
        for s in scenes:
            required = ['scene_number','scene_location','characters_present','scene_purpose','core_action','conflict_point','emotional_shift','scene_outcome']
            missing = [f for f in required if f not in s]
            if missing:
                print(f'    Scene {s[\"scene_number\"]}: MISSING {missing}')
            else:
                print(f'    Scene {s[\"scene_number\"]}: OK')
print('turning_points: act_one=' + str(bool(data['act_one'].get('turning_point'))) + ', act_two=' + str(bool(data['act_two'].get('turning_point'))))
""}

